nextflow_workflow {

    name "Test Subworkflow FAA_SEQFU_SEQKIT"
    script "../main.nf"
    workflow "FAA_SEQFU_SEQKIT"
    config './nextflow.config'

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/faa_seqfu_seqkit"
    tag "seqfu/stats"
    tag "seqkit/seq"
    tag "seqkit/rmdup"
    tag "seqkit/replace"

    test("faa") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id: 'test_faa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome_test.faa', checkIfExists: true)
                ])
                input[1] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }

    test("faa - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id: 'test_stub' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome_test.faa', checkIfExists: true)
                ])
                input[1] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }
}

process {
    withName: SEQFU_STATS_BEFORE {
        ext.prefix = { "${meta.id}_before" }
    }

    withName: SEQFU_STATS_AFTER {
        ext.prefix = { "${meta.id}_after" }
    }

    withName: SEQKIT_SEQ {
        ext.args = [
            "--remove-gaps",
            "--upper-case",
            "--validate-seq",
            "--min-len 30",
            "--max-len 5000"
        ].join(' ').trim()
        ext.prefix = "intermediate_seqkit_seq"
    }

    withName: SEQKIT_REPLACE {
        ext.args   = '-p "/" -r "_"'
        ext.prefix = "intermediate_seqkit_replace"
    }
}
